# -*- coding: utf-8 -*-
"""Documentation consistency: what SKILL.md / README / references name must exist, and SKILL.md must stay an index."""
import re

import yaml

from conftest import SCRIPTS, SKILL, read

DOCS = [SKILL / "SKILL.md", SKILL / "README.md", SKILL / "references" / "routing.md", SKILL / "references" / "gates.md",
        *sorted((SKILL / "references" / "phases").glob("*.md"))]
# scripts that live in the user's project (or are generated by bundle.py), not in scripts/
PROJECT_SIDE = {"train.py", "eval.py", "model.py", "datasets.py", "agentic.py", "check_env.py", "audit_summary.py", "search_literature.py",
                "snowball.py", "triage.py", "fix_pubmed_dois.py", "make_tables.py", "conftest.py", "setup.py"}


def _frontmatter():
    m = re.match(r"(?s)^---\n(.*?)\n---\n(.*)$", read(SKILL / "SKILL.md"))
    assert m, "SKILL.md must start with a YAML frontmatter block"
    return yaml.safe_load(m.group(1)), m.group(2)


def test_frontmatter_is_valid_and_bounded():
    fm, body = _frontmatter()
    assert fm["name"] == SKILL.name == "topic-to-paper"
    assert 200 <= len(fm["description"]) <= 1024          # Claude Code caps the description at 1024 characters
    assert re.match(r"^\d+\.\d+\.\d+$", str(fm["version"]))
    assert len(body.encode("utf-8")) <= 12_000, "SKILL.md body grew past 12 KB: move detail into references/phases/, keep SKILL.md an index"


def test_every_named_script_exists():
    have = {p.name for p in SCRIPTS.glob("*.py")}
    missing = {}
    for d in DOCS:
        for name in set(re.findall(r"(?<![\w/.\-])([a-z_][a-z0-9_]*\.py)\b", read(d))):
            if name not in have and name not in PROJECT_SIDE:
                missing.setdefault(name, []).append(d.name)
    assert not missing, f"scripts named in docs but absent from scripts/: {missing}"


def test_every_named_reference_and_template_exists():
    missing = {}
    for d in DOCS:
        for rel in set(re.findall(r"\b((?:references|templates)/[\w\-./]+?\.(?:md|csv|yaml))", read(d))):
            if "*" in rel or "<" in rel: continue
            if not (SKILL / rel).exists():
                missing.setdefault(rel, []).append(d.name)
    assert not missing, f"paths named in docs that do not exist: {missing}"


def test_phase_files_exist_and_are_linked():
    sk = read(SKILL / "SKILL.md")
    for sid in [f"P{n}" for n in range(9)] + [f"S{n}" for n in range(7)]:
        p = SKILL / "references" / "phases" / f"{sid}.md"
        assert p.exists(), p
        assert f"references/phases/{sid}.md" in sk, f"SKILL.md does not link {sid}.md"
        t = read(p)
        assert t.startswith(f"# {sid} "), f"{sid}.md must start with its stage heading"
        assert len(t) > 200, f"{sid}.md lost its stage text"


def test_readme_script_count_matches():
    m = re.search(r"scripts/\s+(\d+) gate/generator scripts", read(SKILL / "README.md"))
    assert m, "README layout line for scripts/ missing"
    assert int(m.group(1)) == len(list(SCRIPTS.glob("*.py"))), "README's script count is stale"


def test_gates_md_has_a_heading_per_gate():
    g = read(SKILL / "references" / "gates.md")
    for gate in ("G0", "G1", "G1b", "G2", "G3", "G3b", "G4", "G5", "G6", "G6b", "G6c", "G6d", "G6e", "G6f", "G7", "G8"):
        assert re.search(rf"(?m)^## {re.escape(gate)}\b", g), f"gates.md has no '## {gate}' heading"
